@Transactional(propagation = Propagation.REQUIRED, isolation = Isolation.REPEATABLE_READ, rollbackFor = Exception.class)
public void executeTransfer(Long sourceAccountId, Long targetAccountId, BigDecimal amount) {
    Account source = accountRepository.findByIdForUpdate(sourceAccountId)
        .orElseThrow(() -> new AccountNotFoundException("Source not found"));

    if (source.getBalance().compareTo(amount) < 0) {
        throw new InsufficientFundsException("Balance too low");
    }

    accountRepository.decrementBalance(sourceAccountId, amount);
    accountRepository.incrementBalance(targetAccountId, amount);
}
